import os,json # Diagnose actual reference discretization differences without modifying any physical label or admission gate.
os.environ['OPENBLAS_NUM_THREADS']='1';os.environ['OMP_NUM_THREADS']='1' # Bound diagnostic CPU work while the other family trains.
import numpy as np # Retain all actual fine integration points and physical volume weights.
import v2_thermal_hex as model # Use the independently checked native C3D20R physical map.
import v2_thermal_hex_refinement as refine # Reuse only exact curved containment and explicitly disclosed comparison interpolation.
def main(): # Decompose the completed coarse/fine discrepancy in space and along the whole loading history.
    ca=model.OUT/'cases/tv2_hex_l0';cb=model.OUT/'cases/tv2_hex_l1';a,ma,ra=refine.old.read(ca);b,mb,rb=refine.old.read(cb);n=mb['node_count'];points=b['xyz'][n:];element,natural,residual=refine.locate(a,points);assert np.all(element>=0);coarse=refine.sample(a,element,natural);fine=b['states'][:,n:];_,weight=model.quad.reference_gradients(b['fe_xyz'],b['conn']);weight=weight.ravel();s=coarse[:,:,4:10]-fine[:,:,4:10];pressure=s[:,:,:3].mean(axis=-1);dev=s.copy();dev[:,:,:3]-=pressure[:,:,None];total=np.sum(s*s,axis=2)*weight[None,:];hydro=3.*pressure**2*weight[None,:];deviator=np.sum(dev*dev,axis=2)*weight[None,:];peeq=(coarse[:,:,10]-fine[:,:,10])**2*weight[None,:] # Decompose the same raw six-component stress norm used by the frozen gate.
    scale=np.asarray(mb['params']);reference=points/np.array([scale[0],scale[1],1.]);x=reference[:,0];z=reference[:,2];cut=np.where(abs(x-50.)<6.,np.sqrt(np.maximum(0.,36.-(x-50.)**2)),0.);surface_distance=np.minimum(reference[:,1]-cut,30.-cut-reference[:,1])*scale[1] # Measure real material distance from either free notched side in the declared physical geometry.
    def summarize(mask): # Report every selected region only as an error decomposition, never as a masked replacement qualification.
        return {'points':int(mask.sum()),'volume_share':float(weight[mask].sum()/weight.sum()),'stress_squared_error_share':float(total[:,mask].sum()/total.sum()),'hydrostatic_squared_error_share':float(hydro[:,mask].sum()/total.sum()),'peeq_squared_error_share':float(peeq[:,mask].sum()/peeq.sum())} # Preserve the entire-domain error as the common denominator.
    regions={'left_grip_x_lt10':summarize(x<10.),'right_grip_x_gt90':summarize(x>90.),'notch_x44_to56':summarize((x>=44.)&(x<=56.)),'near_notch_x40_to60':summarize((x>=40.)&(x<=60.)),'outer_body_x_lt40_or_gt60':summarize((x<40.)|(x>60.))} # Distinguish physical clamp concentrations from the localized nonlinear notch region.
    distance_bins=[] # Preserve disjoint near-surface and interior contributions.
    for lower,upper in zip([0.,.5,1.,2.,4.,8.],[.5,1.,2.,4.,8.,100.]):distance_bins.append({'range_mm':[lower,upper],**summarize((surface_distance>=lower)&(surface_distance<upper))}) # Do not discard stress or plastic fields near any material boundary.
    thickness_bins=[] # Reveal whether the transient thermal surface or bulk thickness controls the discrepancy.
    for lower,upper in [(0.,5.),(5.,10.),(10.,15.),(15.,20.00001)]:thickness_bins.append({'reference_z_mm':[lower,upper],**summarize((z>=lower)&(z<upper))}) # Preserve both thermal and mechanical through-thickness error contributions.
    phases=[] # Retain every initial and actual endpoint rather than selecting only an easy loading stage.
    for step,control in enumerate(b['controls']):phases.append({'step':step,'time_s':float(control[0]),'drive_mm':float(control[2]),'heater_C':float(control[3]),'stress_squared_error_share':float(total[step].sum()/total.sum()),'hydrostatic_fraction_of_step_stress_error':float(hydro[step].sum()/max(total[step].sum(),1.e-30)),'peeq_squared_error_share':float(peeq[step].sum()/peeq.sum())}) # Identify unloading or thermal-lag phases from the prescribed physical history itself.
    native_p=fine[:,:,:3].mean(axis=-1) # Keep a placeholder-free distinction between stress channels and nodal displacement slots.
    result={'status':'DIAGNOSTIC_ONLY_REFERENCE_REMAINS_HOLD','source_sha256':model.sha(__file__),'coarse':str(ca),'fine':str(cb),'fine_points':len(points),'common_volume_fraction':1.,'stress_norm':'Native six-component ordinary L2, not a tensor Frobenius norm','hydrostatic_fraction_of_stress_squared_error':float(hydro.sum()/total.sum()),'deviatoric_fraction_of_stress_squared_error':float(deviator.sum()/total.sum()),'regions':regions,'free_side_distance_bins':distance_bins,'thickness_bins':thickness_bins,'phases':phases,'interpretation_limit':'Localization and quadrature differences identify where the discrete error occurs; they do not independently prove volumetric locking, a geometric singularity, or the asymptotic convergence rate.'};model.write_json(model.OUT/'mesh_l0_l1_error_localization.json',result);print(json.dumps(result,indent=2)) # Preserve quantitative evidence before choosing any bounded additional native experiment.
if __name__=='__main__':main() # Read only the two already completed native histories.
